import React, { useEffect, useRef } from "react";
import { motion } from "framer-motion";
import { ArrowDown, Thermometer, Microscope } from "lucide-react";
import Button from "../ui/Button";

const container = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.12, delayChildren: 0.3 } },
};
const item = {
  hidden: { opacity: 0, y: 28 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.7, ease: [0.25, 0.46, 0.45, 0.94] } },
};

export default function Hero() {
  const canvasRef = useRef(null);

  // Subtle particle canvas
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    let animId;
    let w = (canvas.width = canvas.offsetWidth);
    let h = (canvas.height = canvas.offsetHeight);

    const particles = Array.from({ length: 40 }, () => ({
      x: Math.random() * w,
      y: Math.random() * h,
      r: Math.random() * 1.5 + 0.5,
      dx: (Math.random() - 0.5) * 0.3,
      dy: (Math.random() - 0.5) * 0.3,
      a: Math.random() * 0.4 + 0.05,
    }));

    const draw = () => {
      ctx.clearRect(0, 0, w, h);
      particles.forEach((p) => {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(255,255,255,${p.a})`;
        ctx.fill();
        p.x += p.dx;
        p.y += p.dy;
        if (p.x < 0 || p.x > w) p.dx *= -1;
        if (p.y < 0 || p.y > h) p.dy *= -1;
      });
      animId = requestAnimationFrame(draw);
    };
    draw();

    const handleResize = () => {
      w = canvas.width = canvas.offsetWidth;
      h = canvas.height = canvas.offsetHeight;
    };
    window.addEventListener("resize", handleResize);
    return () => {
      cancelAnimationFrame(animId);
      window.removeEventListener("resize", handleResize);
    };
  }, []);

  const scrollDown = () => {
    document.getElementById("cold-chain")?.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <section className="relative min-h-screen flex overflow-hidden bg-charcoal-950">
      {/* Background gradient */}
      <div className="absolute inset-0 bg-gradient-to-br from-blue-950 via-charcoal-950 to-charcoal-950" />

      {/* Grid pattern */}
      <div className="absolute inset-0 grid-pattern opacity-100 pointer-events-none" />

      {/* Glow orb */}
      <div className="absolute top-[-15%] right-[20%] w-[600px] h-[600px] rounded-full bg-blue-800/10 blur-[100px] pointer-events-none" />
      <div className="absolute bottom-[-10%] left-[10%] w-[400px] h-[400px] rounded-full bg-blue-700/8 blur-[80px] pointer-events-none" />

      {/* Particle canvas */}
      <canvas
        ref={canvasRef}
        className="absolute inset-0 w-full h-full pointer-events-none"
        style={{ opacity: 0.6 }}
      />

      <div className="relative z-10 max-w-7xl mx-auto px-6 lg:px-10 flex flex-col lg:flex-row items-center min-h-screen py-28 lg:py-0 gap-16">
        {/* Left — content */}
        <motion.div
          variants={container}
          initial="hidden"
          animate="visible"
          className="flex-1 max-w-2xl"
        >
          <motion.div variants={item}>
            <span className="inline-flex items-center gap-2 bg-blue-800/15 border border-blue-800/25 text-blue-300 text-[10.5px] font-bold tracking-[0.2em] uppercase px-4 py-2 rounded-full mb-8">
              <span className="w-1.5 h-1.5 rounded-full bg-blue-400 animate-pulse" />
              Specialist Portfolio · Kenya & East Africa
            </span>
          </motion.div>

          <motion.h1
            variants={item}
            className="font-display text-[clamp(2.8rem,6vw,5rem)] text-white leading-[1.05] mb-7"
          >
            Cold Chain &{" "}
            <em className="text-blue-400 not-italic">Pathology</em>
            <br />
            Infrastructure
            <br />
            <span className="text-white/40 text-[clamp(2rem,4vw,3.5rem)]">That Performs.</span>
          </motion.h1>

          <motion.p
            variants={item}
            className="text-white/55 text-[1.05rem] leading-[1.85] mb-10 max-w-lg"
          >
            A focused showcase of Baylem's advanced cold chain storage systems,
            histopathology laboratories, and mortuary infrastructure delivered
            across all 47 counties of Kenya.
          </motion.p>

          <motion.div variants={item} className="flex flex-wrap gap-4">
            <Button
              variant="primary"
              onClick={() => document.getElementById("cold-chain")?.scrollIntoView({ behavior: "smooth" })}
              icon={<Thermometer size={15} />}
            >
              Cold Chain Solutions
            </Button>
            <Button
              variant="ghost"
              onClick={() => document.getElementById("pathology")?.scrollIntoView({ behavior: "smooth" })}
              icon={<Microscope size={15} />}
            >
              Pathology Systems
            </Button>
          </motion.div>

          {/* Stats row */}
          <motion.div variants={item} className="flex gap-8 mt-14 pt-10 border-t border-white/10">
            {[
              { n: "15+", l: "Years" },
              { n: "200+", l: "Projects" },
              { n: "47", l: "Counties" },
            ].map(({ n, l }) => (
              <div key={l}>
                <div className="font-display text-3xl text-white leading-none">{n}</div>
                <div className="text-white/35 text-[11px] font-semibold tracking-[0.15em] uppercase mt-1">{l}</div>
              </div>
            ))}
          </motion.div>
        </motion.div>

        {/* Right — two stacked capability cards */}
        <motion.div
          initial={{ opacity: 0, x: 60 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.9, delay: 0.5, ease: [0.25, 0.46, 0.45, 0.94] }}
          className="flex-shrink-0 w-full lg:w-[380px] flex flex-col gap-3"
        >
          {/* Cold Chain card */}
          <HeroCapabilityCard
